import typing
from collections import deque
from threading import Lock
from concurrent.futures import ThreadPoolExecutor
import inspect

from pypeln import utils as pypeln_utils
from . import utils


class Stage:
    def __init__(
        self,
        f: typing.Callable,
        workers: int,
        maxsize: int,
        on_start: typing.Callable,
        on_done: typing.Callable,
        dependencies: typing.List["Stage"],
        worker_constructor: typing.Type = None,
    ):

        self.f = f
        self.workers = workers
        self.maxsize = maxsize
        self.on_start = on_start
        self.on_done = on_done
        self.dependencies = dependencies
        self.worker_constructor = worker_constructor
        self.output_queues = utils.MultiQueue()

        self.pipeline_namespace = pypeln_utils.Namespace()
        self.pipeline_namespace.error = None

    def __or__(self, stage):
        return stage(self)

    def __ror__(self, stage):
        return self(stage)

    def to_iterable(self, maxsize: int = 0):
        # Simple synchronous processing for sync module
        # We ignore the workers parameter for sync module and always use sequential processing

        if self.dependencies:
            # Collect all inputs from dependencies
            inputs = []
            for dep in self.dependencies:
                if hasattr(dep, 'to_iterable'):
                    input_iterable = dep.to_iterable(maxsize=maxsize)
                else:
                    input_iterable = dep

                if not hasattr(input_iterable, '__iter__') or isinstance(input_iterable, str):
                    input_iterable = [input_iterable]

                inputs.extend(input_iterable)

            # Sequential processing for sync module (always workers=1 behavior)
            for item in inputs:
                # Handle on_start callback
                kwargs = {}
                if self.on_start:
                    try:
                        sig = inspect.signature(self.on_start)
                        if 'worker_info' in sig.parameters:
                            from .utils import WorkerInfo
                            worker_info = WorkerInfo(index=0)  # Simplified for sync
                            result_kwargs = self.on_start(worker_info)
                        else:
                            result_kwargs = self.on_start()
                    except Exception:
                        # Fallback to default if on_start fails
                        result_kwargs = {}

                    if result_kwargs is None:
                        result_kwargs = {}
                    kwargs = result_kwargs

                try:
                    # Process the item using the apply method for subclasses like FlatMap
                    # But only if the class is not the base Stage class itself
                    if hasattr(self, 'apply') and self.__class__.__name__ != 'Stage':
                        # For subclasses like FlatMap, use apply method
                        self.apply(item, **kwargs)
                    else:
                        # For regular cases, use the f function
                        if self.f is not None:
                            result = self.f(item, **kwargs)

                            # Handle generator/iterable results (important for flat_map)
                            if hasattr(result, '__iter__') and not isinstance(result, str):
                                # Put each item from the iterable into output queues
                                for item in result:
                                    self.output_queues.put(item)
                            else:
                                # Put single item
                                self.output_queues.put(result)
                        else:
                            # For concat-like operations, put the item directly
                            self.output_queues.put(item)
                except Exception as e:
                    # Store the error in the pipeline namespace
                    if self.pipeline_namespace.error is None:
                        self.pipeline_namespace.error = e
                    raise
                finally:
                    # Handle on_done callback
                    if self.on_done:
                        try:
                            # Pass the kwargs to on_done as well
                            self.on_done(**kwargs)
                        except Exception:
                            # Silently ignore errors in on_done callbacks
                            pass

            # Now yield all items from our output queue
            # This ensures proper coordination with other stages
            while not self.output_queues.empty():
                try:
                    item = self.output_queues.get()
                    yield item
                except IndexError:
                    break
        else:
            # Direct iterable for from_iterable
            if hasattr(self, 'iterable'):
                for item in self.iterable:
                    yield item

    def __iter__(self):
        return iter(self.to_iterable())
